27: void ElaApplication::setWindowDisplayMode(ElaApplicationType::WindowDisplayMode windowDisplayType)
28: {
29:     Q_D(ElaApplication);
30:     auto lastDisplayMode = d->_pWindowDisplayMode;
31:     if (lastDisplayMode == windowDisplayType)
32:     {
33:         return;
34:     }
35:     if (lastDisplayMode == ElaApplicationType::ElaMica)
36:     {
37:         d->_resetAllMicaWidget();
38:     }
39:     switch (windowDisplayType)
40:     {
41:     case ElaApplicationType::Normal:
42:     {
43:         break;
44:     }
45:     case ElaApplicationType::ElaMica:
46:     {
47:         d->_pWindowDisplayMode = windowDisplayType;
48:         d->_initMicaBaseImage(QImage(d->_pElaMicaImagePath));
49:         break;
50:     }
51:     default:
52:     {
53:         break;
54:     }
55:     }
56: #ifdef Q_OS_WIN
57:     for (auto widget: d->_micaWidgetList)
58:     {
59:         ElaWinShadowHelper::getInstance()->setWindowDisplayMode(widget, windowDisplayType, lastDisplayMode);
60:         ElaWinShadowHelper::getInstance()->setWindowThemeMode(widget->winId(), d->_themeMode == ElaThemeType::Light);
61:     }
62: #endif
63:     if (windowDisplayType != ElaApplicationType::ElaMica)
64:     {
65:         d->_pWindowDisplayMode = windowDisplayType;
66:         Q_EMIT pWindowDisplayModeChanged();
67:     }
68: }
