106: void ElaApplication::syncWindowDisplayMode(QWidget* widget, bool isSync)
107: {
108:     Q_D(ElaApplication);
109:     if (!widget)
110:     {
111:         return;
112:     }
113:     if (isSync)
114:     {
115:         d->_micaWidgetList.append(widget);
116:         widget->installEventFilter(d);
117:     }
118:     else
119:     {
120:         d->_micaWidgetList.removeOne(widget);
121:         widget->removeEventFilter(d);
122:     }
123:     switch (d->_pWindowDisplayMode)
124:     {
125:     case ElaApplicationType::Normal:
126:     case ElaApplicationType::ElaMica:
127:     {
128:         if (isSync)
129:         {
130:             if (d->_pWindowDisplayMode == ElaApplicationType::WindowDisplayMode::ElaMica)
131:             {
132:                 d->_updateMica(widget, false);
133:             }
134:         }
135:         break;
136:     }
137:     default:
138:     {
139: #ifdef Q_OS_WIN
140:         if (isSync)
141:         {
